import itertools, numpy as np
from collections import Counter
from bigram import corpus, sets      # the two 5-sentence sets above

def distinct_n(sents, n=2):
    grams = [tuple(s.split()[i:i+n]) for s in sents
             for i in range(len(s.split()) - n + 1)]
    return len(set(grams)) / sum(len(s.split()) for s in sents)

def lcs(a, b):
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            dp[i+1][j+1] = dp[i][j] + 1 if x == y else max(dp[i][j+1], dp[i+1][j])
    return dp[-1][-1]

def rouge_l(a, b):
    a, b = a.split(), b.split()
    return 2 * lcs(a, b) / (len(a) + len(b))

def self_rouge(sents):            # mean over all pairs: higher = more alike
    return np.mean([rouge_l(a, b) for a, b in itertools.combinations(sents, 2)])

def spread(sents):                # mean pairwise cosine distance, bag of words
    vocab = sorted({w for s in sents for w in s.split()})
    V = np.array([[s.split().count(w) for w in vocab] for s in sents], float)
    V /= np.linalg.norm(V, axis=1, keepdims=True)
    return np.mean([1 - V[i] @ V[j] for i, j in itertools.combinations(range(len(V)), 2)])

counts = Counter(w for s in corpus for w in s.split())
rare = {w for w, c in counts.items() if c == 1}
def rare_cover(sents):
    seen = {w for s in sents for w in s.split()}
    return len(rare & seen) / len(rare)

for t, ss in sets.items():
    print(f"T={t}: distinct-2 {distinct_n(ss):.2f}  self-ROUGE-L {self_rouge(ss):.2f}"
          f"  spread {spread(ss):.2f}  rare words covered {rare_cover(ss):.2f}")

def lcs(a, b):
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a)):
        for j in range(len(b)):
            dp[i+1][j+1] = dp[i][j] + 1 if a[i] == b[j] else max(dp[i][j+1], dp[i+1][j])
    return dp[-1][-1]

def rouge_l(a, b):
    a, b = a.lower().split(), b.lower().split()
    m = lcs(a, b)
    return 0.0 if m == 0 else 2 * m / (len(a) + len(b))

pool = ["Write a poem about rain", "Sort a list of numbers"]
candidates = ["Write a short poem about rain",
              "Translate this sentence to French",
              "Sort a list of numbers in reverse"]
for c in candidates:
    best = max(rouge_l(c, p) for p in pool)
    if best < 0.7:
        pool.append(c)
    print(c, round(best, 2), len(pool))

from difflib import SequenceMatcher

def ngrams(text, n=10):
    w = text.lower().split()
    return {tuple(w[i:i+n]) for i in range(len(w) - n + 1)}

def contaminated(sample, bench, n=10, cut=0.5):
    if not ngrams(sample, n) & ngrams(bench, n):
        return False, 0.0                     # no shared 10-gram: not a candidate
    m = SequenceMatcher(None, sample, bench)
    matched = sum(b.size for b in m.get_matching_blocks())
    return matched / len(bench) > cut, round(matched / len(bench), 2)

bench = ("Which gas makes up most of the air that we breathe on Earth "
         "at sea level today")
copied = ("Chapter 3. " + bench + "? The answer is nitrogen, about 78 percent.")
reworded = ("What gas forms the largest share of the air people breathe "
            "at sea level? Nitrogen, roughly 78 percent.")
for name, s in [("copied", copied), ("reworded", reworded)]:
    print(name, contaminated(s, bench))
